#include "bench_support.hpp"
using namespace bench;
struct Perturbed:EphemerisProvider { const EphemerisProvider& source; explicit Perturbed(const EphemerisProvider& p):source(p){} EphemerisState geometric_state(int target,Epoch e)const override {auto s=source.geometric_state(target,e);s.position_m=s.position_m+InertialVector{3e-5,0,0};return s;} };
int main(){SpiceEphemerisProvider direct({"/tmp/leo_cspice/kernels/naif0012.tls","/tmp/leo_cspice/kernels/de432s.bsp"});Perturbed perturbed(direct);const auto rhs=dynamics(true);EarthEnvironment a(Earth{},Epoch{0},&direct,true),b(Earth{},Epoch{0},&perturbed,true);auto samples=times(21600);auto baseline=propagate(EnvironmentalDynamics(rhs,a),initial(),Epoch{0},samples,tolerances());auto candidate=propagate(EnvironmentalDynamics(rhs,b),initial(),Epoch{0},samples,tolerances());const auto& x=baseline.samples.back().state;const auto& y=candidate.samples.back().state;Json j;j.add("sun_x_perturbation_m",3e-5);j.add("duration_s",21600.);j.add("final_position_difference_m",norm(x.r-y.r));j.add("final_velocity_difference_m_s",norm(x.v-y.v));j.add("final_attitude_difference_rad",angle(x.q,y.q));j.add("final_omega_difference_rad_s",norm(x.omega-y.omega));std::cout<<j.str()<<'\n';}
